SELECT "APPLICATION" AS "APPLICATION", COUNT(*) AS count 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' GROUP BY "APPLICATION" ORDER BY COUNT(*) DESC 
 LIMIT 3;

SELECT DATE_TRUNC('day', "@timestamp_date") AS "@timestamp_date", CASE WHEN ("APPLICATION" = 'BILLING' OR "APPLICATION" = 'PAYROLL' OR "APPLICATION" = 'ORDERS') THEN "APPLICATION" ELSE 'Others' END AS "APPLICATION", COUNT(*) AS count 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' GROUP BY DATE_TRUNC('day', "@timestamp_date"), CASE WHEN ("APPLICATION" = 'BILLING' OR "APPLICATION" = 'PAYROLL' OR "APPLICATION" = 'ORDERS') THEN "APPLICATION" ELSE 'Others' END;